//! Ultimate Wilderness shared spell list.
//!
//! Generated by `src/bin/ingest_spells.rs` (config-driven, all
//! books) from the real `pathfinder/paizo/roleplaying_game/ultimate_wilderness/uw_spells.lst` corpus. Record coverage: every
//! real, active (non-`.MOD`, non-`.COPY=`) base spell declaration.
//!
//! `level` is the minimum level across the record's `CLASSES:`/
//! `DOMAINS:` token(s), `None` for the rare record that states
//! neither (never fabricated -- these land `text-complete`, not
//! `ingested-magnitude`, via `v06_work_inventory::classify`'s
//! existing `Some(false)` branch).
//!
//! `school`/`description` are `Option` because a minority of
//! records carry neither token of their own on this book's base
//! row.

/// The full 9-school PF1 spell-school enum, mirroring every other book's
/// own copy exactly.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum Pf1SchoolId {
    Abjuration,
    Conjuration,
    Divination,
    Enchantment,
    Evocation,
    Illusion,
    Necromancy,
    Transmutation,
    Universal,
}

impl Pf1SchoolId {
    pub fn from_corpus_str(raw: &str) -> Option<Self> {
        match raw {
            "Abjuration" => Some(Pf1SchoolId::Abjuration),
            "Conjuration" => Some(Pf1SchoolId::Conjuration),
            "Divination" => Some(Pf1SchoolId::Divination),
            "Enchantment" => Some(Pf1SchoolId::Enchantment),
            "Evocation" => Some(Pf1SchoolId::Evocation),
            "Illusion" => Some(Pf1SchoolId::Illusion),
            "Necromancy" => Some(Pf1SchoolId::Necromancy),
            "Transmutation" => Some(Pf1SchoolId::Transmutation),
            "Universal" => Some(Pf1SchoolId::Universal),
            _ => None,
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SpellListEntry {
    pub key: &'static str,
    /// `decisions.md §24`: `Some(line)` ONLY when `key` above
    /// is a Codex-generated neutral identity (the row's real
    /// name is Product Identity) -- carries the real citation
    /// line so `cache_gen::spell_lane_dump` can resolve it
    /// without a name-based lookup. `None` for an ordinary entry.
    pub name_pi_line: Option<u32>,
    pub school: Option<Pf1SchoolId>,
    pub level: Option<u8>,
    pub description: Option<&'static str>,
}

pub const SPELL_LIST: &[SpellListEntry] = &[
    SpellListEntry { key: "Alpha Instinct", name_pi_line: None, school: Some(Pf1SchoolId::Enchantment), level: Some(2), description: Some("Animals perceive you as a social superior. The starting attitude of animals you interact with improves by one step, and you gain a +2 morale bonus on Handle Animal checks. Helpful animals provide simple assistance (such as using the aid another action on skill checks they understand) as long as the spell lasts, but they flee from attacks and do not support you in combat. At one point during the spell's duration, you can issue a nonverbal command to helpful animals within 60 feet to forage for you; the animal or animals immediately head out into the wilderness to do just that. After 1 hour, the animals return to the location where you issued the command to make you an offering of edible food sufficient for one meal for you and (CASTERLEVEL) others.") },
    SpellListEntry { key: "Aquatic Cavalry", name_pi_line: None, school: Some(Pf1SchoolId::Conjuration), level: Some(2), description: Some("You summon a school of (min(6,1+(CASTERLEVEL/3))) hippocampi (Bestiary 2 p155) to serve as combat-trained mounts. The hippocampi avoid combat if possible but defend themselves if attacked. If any hippocampus attacks, the remaining duration of the spell changes from (CASTERLEVEL) hours to (CASTERLEVEL) rounds (so if a full 4 hours remained, the hippocampi last for only 4 more rounds).") },
    SpellListEntry { key: "Bleed for Your Master", name_pi_line: None, school: Some(Pf1SchoolId::Enchantment), level: Some(2), description: Some("When you would be hit by an attack that requires an attack roll, or when you are within an area of effect that allows you to attempt a Reflex saving throw, with a single touch you compel the target to throw itself in front of the blow or shield you from the effect. If an attack roll triggered this spell's casting, the target takes the damage instead of you, even if the attack roll would not normally hit the target's Armor Class. If an area of effect that allows you to attempt a Reflex save triggered this spell's casting, the target instead grants you cover against the effect (+2 bonus on Reflex saves) if it is your size or smaller, or improved cover (+4 bonus on Reflex saves and improved evasion against the effect) if it is larger than you. The target automatically fails its Reflex save against the effect but can still benefit from improved evasion and similar mitigating effects. After taking damage, the target is shaken for 1 minute. If the target was already shaken, it becomes frightened instead.") },
    SpellListEntry { key: "Callback", name_pi_line: None, school: Some(Pf1SchoolId::Conjuration), level: Some(2), description: Some("If the target takes hit point damage while within range of this spell, it immediately teleports to your space (or adjacent to your space) after the damage is applied. If the target is killed, its corpse teleports instead. Optionally, you can specify a number of points of damage for your familiar to take before the spell takes effect, but you must do so when the spell is cast. Once the familiar has teleported back to you, the spell ends.") },
    SpellListEntry { key: "Callback (Greater)", name_pi_line: None, school: Some(Pf1SchoolId::Conjuration), level: Some(5), description: Some("If the target takes hit point damage while within range of this spell, it immediately teleports to your space (or adjacent to your space) after the damage is applied. If the target is killed, its corpse teleports instead. Optionally, you can specify a number of points of damage for your familiar to take before the spell takes effect, but you must do so when the spell is cast. Once the familiar has teleported back to you, the spell ends.") },
    SpellListEntry { key: "Cave Fangs", name_pi_line: None, school: Some(Pf1SchoolId::Conjuration), level: Some(5), description: Some("You create a magical trap in the area that causes deadly stalactites or stalagmites to lurch out of the floor or ceiling of a stone surface to \"bite\" an intruder. The magical trap is triggered whenever a Small or larger creature (other than you or your animal companion, familiar, or spirit animal) moves through the affected area. The effect of cave fangs depends on whether you create stalactites or stalagmites (see below). You can place these trapped squares anywhere within the spell's range; they need not be adjacent to each other, and you can create any mix of stalactites and stalagmites you wish. Cave fangs can be detected and disarmed as per a magical trap with successful DC 30 Perception and Disable Device checks. All trapped squares created by a single casting are linked, and they are all disabled if one of them is. If you place the traps in an area that is occupied by a creature, the spell effect is triggered at the completion of the casting. [Stalactites] Shards of rock drop from the ceiling, dealing 3d8 points of bludgeoning and piercing damage (Reflex half) and creating an area of dense rubble that costs 2 squares of movement to enter. Dense rubble adds 5 to the DC of Acrobatics checks and adds 2 to the DCs of Stealth checks. A creature that fails its Reflex save is pinned to the ground under stalactites and rubble, gaining the entangled condition until it can free itself with a successful DC 15 Strength check or DC 20 Escape Artist check. One Small or larger creature can automatically clear the rubble by working for 1 minute. [Stalagmites] Piercing spires of rock erupt up from the ground, dealing 3d8 points of piercing damage and knocking the creature prone (a creature that succeeds at a Reflex saving throw takes half damage and avoids being knocked prone). Once the stalagmites appear, they function thereafter as spike stones for 1 minute per caster level and then crumble to dust. If cave fangs is cast inside of a cave or cavern, each effect of the spell deals 4d8 points of damage instead of 3d8, and creatures that trigger the cave fangs take a -2 penalty on their saving throws against the spell's effect. [Material Component; a sharp gemstone fragment worth 150 gp]") },
    SpellListEntry { key: "Companion Transposition", name_pi_line: None, school: Some(Pf1SchoolId::Conjuration), level: Some(4), description: Some("You trade places with the other target, teleporting as if you were both affected by dimension door. Both you and the other target arrive in a square you choose in the other's former space. If the targets are different sizes, they must appear in locations that cover previously occupied squares. As with dimension door, after casting this spell, you can't take any other actions until your next turn, and the other target is staggered until the end of its next turn due to the transposition.") },
    SpellListEntry { key: "Earth Tremor", name_pi_line: None, school: Some(Pf1SchoolId::Transmutation), level: Some(3), description: Some("You strike the ground and unleash a tremor of seismic force, hurling up earth, rock, and sand. You choose whether the earth tremor affects a 30-foot line, a 20-foot cone-shaped spread, or a 10-foot-radius spread centered on you. The space you occupy is not affected by earth tremor. The area you choose becomes dense rubble that costs 2 squares of movement to enter. Dense rubble adds 5 to the DC of Acrobatics checks and adds 2 to the DC of Stealth checks. Creatures on the ground in the area take (min(10,CASTERLEVEL))d4 points of bludgeoning damage or half damage on a successful save. Medium or smaller creatures that fail their saves are knocked prone. This spell can be cast only on a surface of earth, sand, or stone. It has no effect if you are in a wooden or metal structure or if you are not touching the ground.") },
    SpellListEntry { key: "Echo", name_pi_line: None, school: Some(Pf1SchoolId::Illusion), level: Some(1), description: Some("You cause a sound heard in the target area up to 1 round ago and lasting up to 1 round in duration to repeat at a regular interval. The original sound need not have come from the area, but it echoes from the target area at its original full volume. Any special effects of the sound are not duplicated by this spell. If the area is naturally prone to echoes, such as a space surrounded on at least two sides by cliffs or high river banks, the spell's range is long. Otherwise, the spell's range is close. You can concentrate as a standard action to alter the echo. You can change it to be any sound audible in the area within the last 1 round, move the apparent source of the sound within the area, or attempt a Bluff check to create a distraction to hide with a +(CASTERLEVEL) bonus.") },
    SpellListEntry { key: "Explosion of Rot", name_pi_line: None, school: Some(Pf1SchoolId::Necromancy), level: Some(4), description: Some("You call forth a burst of decay that ravages all creatures in the area. Even nonliving creatures such as constructs and undead crumble or wither in this malignant eruption of rotting energy. Creatures in the area of effect take (min(15,CASTERLEVEL))d6 points of damage and are staggered for 1d4 rounds. A target that succeeds at a Reflex saving throw takes half damage and negates the staggered effect. Plant creatures are particularly susceptible to this rotting effect; a plant creature caught in the burst takes a -2 penalty on the saving throw and takes 1 extra point of damage per die.") },
    SpellListEntry { key: "Fey Form I", name_pi_line: None, school: Some(Pf1SchoolId::Transmutation), level: Some(3), description: Some("You assume the form of a Small or Medium creature of the fey type. Your base speed changes to match the new form's base speed, with a maximum speed of 60 feet (even if the chosen fey form has a base speed in excess of that speed). If the form you assume has any of the following abilities, you gain those abilities: climb speed 30 feet, fly speed 30 feet (average maneuverability), swim speed 30 feet, darkvision 60 feet, low-light vision, scent, and boot stomp. If the form you assume has the aquatic subtype, you can breathe air and water. If the creature has any weaknesses, you gain those weaknesses. If a listed ability depends on an item (as is the case with boot stomp), this spell transforms the nearest counterpart among your worn gear into that item. You can more easily cast spells that the creature has as spell-like abilities, although you must still cast them as normal for your class. When you cast a spell that the creature has as a spell-like ability, it requires no verbal or somatic components and can't be countered. [Small Fey] If you assume this form, you gain a +2 size bonus to your Dexterity and Constitution scores. [Medium Fey] If you assume this form, you gain a +2 size bonus to your Strength and Constitution scores.") },
    SpellListEntry { key: "Fey Form II", name_pi_line: None, school: Some(Pf1SchoolId::Transmutation), level: Some(5), description: Some("This spell functions as fey form I, except it also allows you to assume the form of a Tiny or Large creature of the fey type. Your base speed can't increase above 90 feet this way. If the form you assume has any of the following abilities, you gain those abilities: burrow speed 30 feet, climb speed 90 feet, fly speed 60 feet (good maneuverability), swim speed 60 feet, all-around vision, blindsense 30 feet, darkvision 60 feet, low-light vision, scent, see in darkness, abduct, animated hair, bleed, blood rage, boot stomp, burn, compression, constrict, crushing leap, DR 2/cold iron, grab, heavy weapons, icewalking, kneecapper, nasal spray, no shadow, oversized weapons, poison, putrid vomit, rock throwing (50 feet, 1d6 damage), sound mimicry, trackless step, trample, tree meld, undersized weapons, and woodland stride. If the creature has immunity to mind-affecting effects or poison, you gain a +4 resistance bonus on saves against those effects. If the creature has any weaknesses, you gain them. [Tiny Fey] If you assume this form, you gain a +6 size bonus to your Dexterity score and take a -2 penalty to your Strength score. [Large Fey] If you assume this form, you gain a +4 size bonus to your Strength and Constitution scores and take a -2 penalty to your Dexterity score.") },
    SpellListEntry { key: "Fey Form III", name_pi_line: None, school: Some(Pf1SchoolId::Transmutation), level: Some(6), description: Some("This spell functions as fey form II except it allows you to assume the form of a Diminutive or Huge creature of the fey type. If the form you assume has any of the following abilities, you gain those abilities: burrow speed 60 feet, climb speed 90 feet, fly speed 90 feet (good maneuverability), swim speed 90 feet, all-around vision, blindsense 60 feet, blindsight 30 feet, darkvision 90 feet, low-light vision, scent, see in darkness, tremorsense 60 feet, abduct, animated hair, bleed, blood rage, boot stomp, burn, compression, constrict, crushing leap, DR 5/cold iron, fear aura, frightful presence, grab, heavy weapons, icewalking, kneecapper, luminous, nasal spray, no shadow, oversized weapons, poison, putrid vomit, rend, rock throwing (100 feet, 2d6 damage), sound mimicry, supernatural speed, tear shadow, trackless step, trample, tree meld, undersized weapons, and woodland stride. If the creature has immunity or resistance to any energy types, you gain resistance 20 to those energy types. If the creature has immunity to mind-affecting effects or poison, you gain a +8 resistance bonus on saves against those effects. If the creature has any weaknesses, you gain those weaknesses. [Diminutive Fey] If you assume this form, you gain a +8 size bonus to your Dexterity score and take a -4 penalty to your Strength score. [Huge Fey] If you assume this form, you gain a +6 size bonus to your Strength and Constitution scores and take a -4 penalty to your Dexterity score.") },
    SpellListEntry { key: "Fey Form IV", name_pi_line: None, school: Some(Pf1SchoolId::Transmutation), level: Some(8), description: Some("This spell functions as fey form III except it doesn't limit your base speed and also allows you to use more abilities. If the form you assume has any of the following abilities, you gain those abilities: burrow speed 60 feet, climb speed 90 feet, fly speed 120 feet (good maneuverability), swim speed 120 feet, all-around vision, blindsense 60 feet, blindsight 30 feet, darkvision 90 feet, low-light vision, scent, see in darkness, tremorsense 60 feet, abduct, animated hair, beguiling aura, bleed, blood rage, boot stomp, burn, compression, constrict, crushing leap, DR 5/cold iron, fast healing 5, fear aura, frightful presence, grab, heavy weapons, hide in plain sight, icewalking, kneecapper, luminous, nasal spray, no shadow, oversized weapons, poison, putrid vomit, rend, rock throwing (120 feet, 2d10 damage), sound mimicry, supernatural speed, tear shadow, trackless step, trample, transparency, tree meld, undersized weapons, vault, and woodland stride. If the creature has immunity or resistance to any energy types, you gain resistance 30 to those energy types. If the creature has immunity to mind-affecting effects or poison, you gain a +8 resistance bonus on saves against those effects. If the creature has spell resistance, you gain spell resistance 6 + your caster level. If the creature has any weaknesses, you gain those weaknesses.") },
    SpellListEntry { key: "Fey Gate", name_pi_line: None, school: Some(Pf1SchoolId::Conjuration), level: Some(6), description: Some("This spell functions as the planar travel function of gate, except it can be used to travel only between points on the Material Plane and the First World, and it comes with additional dangers. This spell forms a circular portal between 5 and 20 feet in diameter (your choice) oriented in the direction you desire when it comes into being (typically vertical and facing you). The portal is full of gray fog that blocks line of sight. Anyone or anything that moves through the portal to enter the First World is shunted instantly to a random point on that plane (the same point for everything traveling via a particular casting). At the end of the spell's duration, the caster can attempt a DC 30 Spellcraft check. On a success, the portal remains open for 1d4+1 days. Creatures exiting the First World through a fey gate always arrive at the location the spell was cast. While the spell always deposits travelers on solid ground in the First World, it conveys no protections against whatever creatures or environmental hazards may be present there.") },
    SpellListEntry { key: "Flashfire", name_pi_line: None, school: Some(Pf1SchoolId::Evocation), level: Some(3), description: Some("You cause flames to spring up in the area of effect. These flames deal (min(5,CASTERLEVEL/3))d6 points of fire damage to each creature that enters a burning area or begins its turn in the area; these creatures also catch on fire. A creature that succeeds at a Reflex save negates the damage and avoids catching on fire. The area and all adjacent 5-foot squares are smoky, providing concealment within. You can concentrate as a standard action to ignite one 5-foot square adjacent to a currently burning square. Heavy precipitation (including sleet storm) ends the spell. Strong and severe winds spread each square of flashfire downwind by one square each round, but windstorm-force or stronger winds extinguish the fires.") },
    SpellListEntry { key: "Forest's Sense", name_pi_line: None, school: Some(Pf1SchoolId::Divination), level: Some(3), description: Some("You can sense the location of a target creature within range if it is also within 10 feet of a living plant or fungus. You must be able to target the creature by tangible qualities such as its build, clothing texture, size, or tracks, but you need not have line of effect to your target. The fungus or plants near the target serve as a scrying sensor for this spell. Your senses of hearing, smell, and touch extend to all fungus and plants within 10 feet of the target, allowing you to gauge the size and shape of nearby objects and potentially to overhear conversations in which the target is currently participating. Your scent ability and tremorsense extend through this scrying sensor if you have them, but any other special senses you might have do not. For 1 day after casting this spell, you gain a +5 insight bonus on Survival checks to track creatures you sensed via the spell. You can dismiss this bonus on Survival checks.") },
    SpellListEntry { key: "Greensight", name_pi_line: None, school: Some(Pf1SchoolId::Transmutation), level: Some(2), description: Some("The target of this spell gains the ability to see up to 60 feet through thick plant matter as though it were transparent. Greenery, leaves, and vines-even lichen, moss, and slime-offer no concealment to the recipient's sight, though her vision still can be blocked by solid wood, such as trees or wooden structures. Undergrowth does not grant concealment to a creature against a target of the effects of greensight.") },
    SpellListEntry { key: "Hidden Spring", name_pi_line: None, school: Some(Pf1SchoolId::Transmutation), level: Some(1), description: Some("You spend 1 hour in quiet meditation, holding the focus component in both hands and walking around a natural area. You are simultaneously drawn to areas of natural moisture while drawing that moisture closer. As the spell's casting time concludes, you thrust the focus component into the ground. From that point, a fresh, clean water trickles forth at a rate of 1 gallon every 10 minutes. You cannot cast this spell inside a building or in an area of worked stone, but you can cast it underground. You cannot cast this spell within 1 mile of an existing hidden spring.") },
    SpellListEntry { key: "Iron Stake", name_pi_line: None, school: Some(Pf1SchoolId::Conjuration), level: Some(2), description: Some("This spell creates a 1-foot-long spike of cold iron that you fling at your target as a ranged touch attack. The stake is treated as a magic and cold iron weapon for the purpose of overcoming damage reduction, and deals (min(10,CASTERLEVEL/2))d6 points of piercing damage. Additionally, if a creature with DR/cold iron takes damage from this spell, it is sickened for 1 round and must attempt a Fortitude save. If it fails, for (CASTERLEVEL) rounds, it must succeed at a concentration check (in addition to any normally required concentration checks) to use any spells or spell-like abilities it has-the DC of this check is equal to 15 + twice the spell's level. If the creature fails this concentration check, its spell is wasted.") },
    SpellListEntry { key: "Magical Beast Shape", name_pi_line: None, school: Some(Pf1SchoolId::Transmutation), level: Some(7), description: Some("This spell functions as beast shape IV except you can assume the form of only a magical beast of a size between Diminutive and Huge. If the form you assume has any of the following abilities, you gain those abilities: burrow speed 60 feet, climb speed 90 feet, fly speed 120 feet (good maneuverability), swim speed 120 feet, blindsense 60 feet, blindsight 30 feet, darkvision 90 feet, low-light vision, scent, see in darkness, tremorsense 60 feet, blood drain, blood frenzy, breath weapon (if damage, up to 12d6 points), constrict, fast healing 5, ferocity, grab, hold breath, jet, no breath, poison, pounce, powerful charge, pull, rake, rend, roar, spikes, trample, trip, and web. If the creature has immunity to poison, you gain a +8 resistance bonus on saves against poison. If the creature has immunity or resistance to any energy types, you gain resistance 20 to those energy types. If the creature has vulnerability to an energy type, you gain that vulnerability. [Diminutive Magical Beast] If you assume this form, you gain a +10 size bonus to your Dexterity score and take a -4 penalty to your Strength score. [Huge Magical Beast] If you assume this form, you gain a +8 size bonus to your Strength score, take a -4 penalty on your Dexterity score, a +2 size bonus to your Constitution score, and gain a +7 natural armor bonus.") },
    SpellListEntry { key: "Merge with Familiar", name_pi_line: None, school: Some(Pf1SchoolId::Transmutation), level: Some(2), description: Some("As long as the target is at least one size category smaller than you are, it can merge harmlessly into your body while under the effect of this spell. For the duration of this spell, you and the target can separate or merge at will as a move action. While merged, your familiar or spirit animal can't be targeted or affected by most attacks and effects, though it still suffers from ongoing effects and their durations continue. It can be the recipient of effects that originate from you.") },
    SpellListEntry { key: "Mirage", name_pi_line: None, school: Some(Pf1SchoolId::Illusion), level: Some(3), description: Some("You create an image of a pool of water, a group of standing stones, a cove, an island, or another simple land formation over a stretch of flat land or water. The image is purely visual, and structures, equipment, and creatures within the area are not hidden or changed in appearance. Anyone interacting with the illusion can attempt to disbelieve it, and a creature trained in Survival can make a special attempt to disbelieve the illusion. The creature must be within 120 feet of the illusion's area and can attempt a Survival check instead of a Will saving throw. If the result is equal to or greater than the spell's save DC, the creature realizes the mirage is an illusion as if it disbelieved the spell.") },
    SpellListEntry { key: "Ooze Form I", name_pi_line: None, school: Some(Pf1SchoolId::Transmutation), level: Some(5), description: Some("You assume the form of a Small or Medium ooze. Regardless of the type of ooze you transform into, you gain base speed 10 feet, climb speed 10 feet, swim speed 20 feet, and blindsense 30 feet. You gain a +4 resistance bonus on saving throws against mind-affecting effects and poison. A wood or metal weapon that strikes you takes acid damage as if from your slam unless the wielder succeeds at a Reflex saving throw. [Small Ooze:] If you assume this form, you gain a +4 size bonus to your Constitution score, a slam attack (1d3 plus 1d3 acid), and constrict (1d3), and take , a -4 penalty to your Dexterity score. [Medium Ooze] If you assume this form, you gain a +6 size bonus to your Constitution score, a -6 penalty to your Dexterity score, a slam attack (1d4 plus 1d4 acid), and constrict (1d4).") },
    SpellListEntry { key: "Ooze Form II", name_pi_line: None, school: Some(Pf1SchoolId::Transmutation), level: Some(6), description: Some("This spell functions as ooze form I except you can also assume the form of a Large ooze. You gain blindsight 30 feet and immunity to critical hits and precision damage as well. [Large Ooze] If you assume this form, you gain a +2 size bonus to your Strength score, a +8 size bonus to your Constitution score, a slam attack (2d4 plus 1d6 acid and grab), and constrict (2d4), and you take a -8 penalty to your Dexterity score.") },
    SpellListEntry { key: "Ooze Form III", name_pi_line: None, school: Some(Pf1SchoolId::Transmutation), level: Some(7), description: Some("This spell functions as ooze form II except you can also assume the form of a Huge ooze. You gain blindsight 60 feet and a +8 resistance bonus on saving throws against mind-affecting effects and poison as well. [Huge Ooze] If you assume this form, you gain a +4 size bonus to your Strength, a +10 size bonus to your Constitution score, a -10 penalty to your Dexterity score, base speed 20 feet, climb speed 20 feet, swim speed 30 feet, a slam attack (2d6 plus 2d6 acid and grab), and constrict (2d6).") },
    SpellListEntry { key: "Pouncing Fury", name_pi_line: None, school: Some(Pf1SchoolId::Transmutation), level: Some(2), description: Some("When you charge, you can make a full attack at the end of that charge, but only with claw attacks you have, and you can make only one attack per claw. If you have abilities that grant bonuses on damage rolls or that apply other special effects to charge attacks, only the first claw attack benefits from these bonuses. When you make a claw attack as an attack of opportunity, you can expend one additional use of your attacks of opportunity to make an additional claw attack against the target that provoked the attack.") },
    SpellListEntry { key: "Replay Tracks", name_pi_line: None, school: Some(Pf1SchoolId::Divination), level: Some(2), description: Some("This spell allows you to reconstruct past events that occurred in your current location based on the tracks and other signs left behind. Replay tracks reveals events that occurred while the tracks that serve as the focus for the spell were being left, revealing events in the order they happened in real time or in reverse, depending on whether you are following the tracks forward or backward, although the image isn't clear enough to make out details (such as a creature's exact identity). You can attempt Survival checks to follow tracks as part of concentrating on the spell, but only events connected to the tracks used as the focus of the spell are revealed by the spell. Elements that left no trace detectable by you, such as creatures benefitting from pass without trace, are absent from the events you visualize.") },
    SpellListEntry { key: "Ropeweave", name_pi_line: None, school: Some(Pf1SchoolId::Transmutation), level: Some(2), description: Some("You cause the target rope to grow in length and weave itself into one of several forms, each of which can support up to (min(3000,(CASTERLEVEL*200)+1000)) pounds. Only one type of construction can be created with each casting of the spell, and the creation remains stationary unless destroyed. Each 5-foot section of the object created by this spell has a break DC of 23, AC 11, and (min(10,CASTERLEVEL)) hit points, but all sections of the creation are magically supported and need not be anchored to a solid surface or any other portion of the effect. Destroying one part of it does not cause the remainder of the structure to collapse, though each 5-foot section destroyed reduces the maximum weight the creation can support by 200 pounds. During any round in which the rope is overloaded, every remaining section takes 1d4 points of damage. You can use ropeweave to create any of the following structures. [Rope Bridge] The rope forms a 5-foot-wide bridge that spans up to (min(100,CASTERLEVEL*10)) feet horizontally. Creatures can cross the bridge at half speed with a successful DC 5 Acrobatics check or at full speed with a successful DC 10 Acrobatics check. The DC assumes a creature is using both hands to assist in navigating the rope bridge; the DC increases by 5 if a creature uses only one hand to steady itself and by 10 if the creature does not use its hands. A failed Acrobatics check results in failure to progress across the rope bridge; creatures that fail by 5 or more fall. [Rope Hammock] The rope knits itself into a stationary hammock suspended in midair. The hammock can be suspended at a height of (min(30,((CASTERLEVEL*5)+5))) feet, with a rope ladder (see below) leading up to a platform of (CASTERLEVEL) five-foot squares, and at least one such square must be adjacent to the square containing the vertical rope ladder. As a move action, the caster can command the rope ladder to withdraw into the hammock. When the ladder is withdrawn, the rope hammock blends in with its surroundings and muffles sounds and smells from creatures resting on it that are taking no violent actions; noticing the rope hammock requires a successful DC 20 Perception check or Survival check, even for creatures with scent. This does not apply if the creatures in the hammock attack or move more than half speed. The hammock provides a +2 cover bonus to AC against attacks from beneath it. [Rope Ladder] The rope knots itself and hangs suspended in midair, perpendicular to the ground, stretching up to (min(100,CASTERLEVEL*10)) feet vertically. Climbing the rope ladder requires a successful DC 5 Climb check, or DC 0 if there is a wall adjacent to it you can brace it against. [Trip Line] The rope stretches into a tangled mass that fills (min(10,CASTERLEVEL)) five-foot squares, all of which must be contiguous (including diagonally). Any creature entering a square with this trip line must succeed at an Acrobatics check (DC = 10 if moving at half speed, DC = 15 if moving at full speed, and DC = 20 if running or charging). On a failed check, the creature's movement stops when it enters the square; a creature that fails by 5 or more falls prone. A creature larger than Medium gains a +2 bonus on its Acrobatics check for every size category larger than Medium it is.") },
    SpellListEntry { key: "Scamper", name_pi_line: None, school: Some(Pf1SchoolId::Transmutation), level: Some(2), description: Some("Your animal companion moves with astonishing agility and speed until the end of its turn. It can move at full speed while using Acrobatics, and it gains a +(min(20,CASTERLEVEL*2)) competence bonus on Acrobatics checks to avoid attacks of opportunity or move through a square occupied by an enemy.") },
    SpellListEntry { key: "Sea of Dust", name_pi_line: None, school: Some(Pf1SchoolId::Transmutation), level: Some(9), description: Some("You cause all areas of water to which you have line of effect to recede as if you had cast control water. Exposed water that enters the area ebbs away, evaporating or leaching into the ground at a rate of 1 foot of depth per hour. Living creatures in the area when the spell is cast are parched with thirst and take a -4 penalty on Constitution checks to resist the effects of a hot climate, and their daily water requirement to avoid thirst doubles (Core Rulebook p444). Plant creatures and inanimate plants take 1d6 points of nonlethal damage per hour after the first 24 hours, which bypasses hardness and damage reduction. Living creatures with the aquatic or water subtype, unless completely immersed in water, must attempt a DC 20 Constitution check each hour no matter how much water they drink. A creature that fails takes 1d6 points of nonlethal damage and becomes fatigued until it recovers from the nonlethal damage. After 1 week, the soil in the area of sea of dust begins to break down and blow away. Moderate winds have a 50%% chance each hour to cause sandstorms (Core Rulebook p431). This chance increases to 75%% in strong winds and 100%% in severe or stronger winds. Short-duration wind effects such as gust of wind create sandstorms with the same area and duration as the spell, plus an identical duration after the spell ends. After 1 month, the soil in an area affected by sea of dust has virtually disintegrated. The area is treated as a shallow bog for the purposes of movement (Core Rulebook p427), with a 25%% chance each hour to encounter an area equivalent to a deep bog 2d6x10 feet across, and a 5%% chance to encounter a collapsing dust drift equivalent to quicksand (Core Rulebook p427) 1d6x5 feet across. The affected region remains desertlike in condition until the magic is dispelled, at which point the region recovers and returns to its original terrain over the course of time (this may take only days or weeks, or it could take months or even years, subject to GM discretion). This spell has no effect if cast on an entirely aquatic region. If the spell is cast on an island, the effects of the spell extend to the shore but not beyond.") },
    SpellListEntry { key: "Sea Stallion", name_pi_line: None, school: Some(Pf1SchoolId::Transmutation), level: Some(4), description: Some("The target adapts to life in the water, gaining piscine scales that cover its body and growing fins in place of feet. It gains the aquatic subtype, the amphibious quality, and a swim speed equal to its base speed before it came under the effect of this spell. While under the effects of this spell, the target's base speed is reduced by 10 feet (minimum 10 feet). As long as you stay mounted on the target, you also gain the amphibious quality and your melee attacks function as if you were under the effect of freedom of movement. The benefits you gain from this spell are not polymorph effects. If you dismount from the target, you retain the amphibious quality for up to 1 minute, but not the other benefits. You regain all of the benefits once you mount the target creature again.") },
    SpellListEntry { key: "Sea Steed", name_pi_line: None, school: Some(Pf1SchoolId::Transmutation), level: Some(2), description: Some("The target adapts to life in the water, gaining piscine scales that cover its body and growing fins in place of feet. It gains the aquatic subtype, the amphibious quality, and a swim speed equal to its base speed before it came under the effect of this spell. While under the effects of this spell, the target's base speed is reduced by 10 feet (minimum 10 feet).") },
    SpellListEntry { key: "Shapechanger's Gift", name_pi_line: None, school: Some(Pf1SchoolId::Transmutation), level: Some(5), description: Some("You change the target into an animal (as per beast shape I), humanoid (as per alter self), or monstrous humanoid (as per monstrous physique I). The chosen form can't have a fly speed. The subject's statistics change as per the appropriate spell except the creature's ability scores and natural armor do not change. The creature can change between its natural form and the chosen form at will as a standard action.") },
    SpellListEntry { key: "Shapechanger's Gift (Greater)", name_pi_line: None, school: Some(Pf1SchoolId::Transmutation), level: Some(7), description: Some("You change the target into an animal (as per beast shape I), elemental (as per elemental body I), fey (as per fey form I), humanoid (as per alter self), monstrous humanoid (as per monstrous physique I), or vermin (as per vermin shape I) and the chosen form can have a fly speed. The subject's statistics change as per the appropriate spell except the creature's ability scores and natural armor do not change. The creature can change between its natural form and the chosen form at will as a standard action.") },
    SpellListEntry { key: "Signs of the Land", name_pi_line: None, school: Some(Pf1SchoolId::Divination), level: Some(3), description: Some("This spell functions as commune with nature except it reveals up to three details about the territory you currently occupy from the following list - bodies of water, features, minerals, or plants. For each feature you learn about, you automatically know the skills you can use to discover that feature and you gain 1d6 Discovery Points toward finding it (see page 124).") },
    SpellListEntry { key: "Sky Steed", name_pi_line: None, school: Some(Pf1SchoolId::Transmutation), level: Some(3), description: Some("The target sprouts angelic wings and gains a fly speed equal to its base speed with average maneuverability. It also gains a bonus on Fly checks equal to your caster level.") },
    SpellListEntry { key: "Snowball", name_pi_line: None, school: Some(Pf1SchoolId::Evocation), level: Some(1), description: Some("You throw a ball of elemental ice and snow at a single targetas a ranged touch attack. The snowball deals (min(5,CASTERLEVEL))d6 points of cold damage.") },
    SpellListEntry { key: "Soothing Mud", name_pi_line: None, school: Some(Pf1SchoolId::Conjuration), level: Some(3), description: Some("You create an area of healing mud. Water, earth, sand, and dust thicken into a wet mud. The mud functions as difficult terrain and does not sink if created in water unless weighed down by more than (CASTERLEVEL*100) pounds. Each round a creature begins its turn in or on the mud, the mud restores 1 hit point to it; this healing is unaffected by effects that increase a creature's healing. A creature that rests partially or completely submerged in this mud for 1 full minute is also healed of 1d4 points of ability damage to an ability score of its choice. A creature can be healed of ability damage this way only once per day.") },
    SpellListEntry { key: "Sturdy Tree Fort", name_pi_line: None, school: Some(Pf1SchoolId::Transmutation), level: Some(4), description: Some("You cause a large tree to grow in the 5-foot square you touch. The tree has (CASTERLEVEL*4) feet of thickness, and it can grow to any height you designate, up to (CASTERLEVEL*5) feet high. If there is a ceiling or other barrier overhead, the maximum height of the tree cannot exceed the space available. At any point along the tree's height, you can create a sturdy wooden building that fills (CASTERLEVEL/4) ten-foot cube(s). All portions of the structure must be adjacent to the trunk of the tree (or can have the tree trunk extend up through their spaces), but otherwise these cubes need not be contiguous. If you place the cubes so that they are contiguous, the buildings merge together, complete with ladders connecting different vertical levels. The fort is magically supported, but if the tree it is attached to is destroyed, the structure is destroyed as well (the tree has hardness 5 and (CASTERLEVEL*20) hp). Each building you create has shuttered arrow slits on its walls and in the floor, granting those within the structure improved cover against attacks from outside while the arrow slits are open and total cover when they are closed. Each cube within the fort is equivalent to a secure shelter, other than the size and its wooded construction material (hardness 5). When you cast sturdy tree fort, you can designate (CASTERLEVEL) creatures. Designated creatures gain a +10 bonus on Climb checks and are not denied their Dexterity bonuses while climbing on the fort's structure, as they find handholds and stable footholds easily on the tree and its buildings. You cannot cast this spell in an area of worked stone, though you can cast it in natural surroundings that would not normally support the growth of a large tree, such as a cavern, desert, or glacier. If you cast this spell in a forest, jungle, or similar heavily treed terrain, the fort is camouflaged as long as its doors and windows remain closed (or even if they are open, as long as those within remain quiet and take no violent actions), requiring a successful DC 25 Perception check or Survival check to notice its presence.") },
    SpellListEntry { key: "Tail Current", name_pi_line: None, school: Some(Pf1SchoolId::Transmutation), level: Some(3), description: Some("You compel the water to push the targets in a direction of your choice. The subjects can hustle during local and overland movement without risk of fatigue. If the subjects are swimming, the first 20 feet of movement each round in the chosen direction does not count against their movement for the round. Each creature remains affected only while within 120 feet of every other subject. You can change the tail current's direction once per hour by concentrating as a standard action. This spell functions only underwater.") },
    SpellListEntry { key: "Tailwind", name_pi_line: None, school: Some(Pf1SchoolId::Transmutation), level: Some(3), description: Some("You compel the wind to push the targets in a direction of your choice. The subjects can hustle during local and overland movement without risk of fatigue. If the subjects are flying, the first 20 feet of movement each round in the chosen direction does not count against their movement for the round. Each creature remains affected only while within 120 feet of every other subject. You can change the tailwind's direction once per hour by concentrating as a standard action. This spell has no effect underwater.") },
    SpellListEntry { key: "Tamer's Lash", name_pi_line: None, school: Some(Pf1SchoolId::Evocation), level: Some(1), description: Some("A 15-foot-long whip of sonic energy springs from your hand, delivering a loud crack when you strike with it. The tamer's lash acts as a whip that deals 1d4 points of sonic damage on a hit, but it has no physical substance and you cannot use it to perform combat maneuvers, nor can it be sundered or disarmed. If you strike an animal with the tamer's lash, the animal must succeed at a Will saving throw or be unable to attack you for 1d3 rounds. Furthermore, if the whipped animal starts its turn unable to attack you as a result of this spell and it is within 30 feet of you, it must spend its first action moving away from you, if it is able. Combat-trained animals, animal companions, and animals with Hit Dice in excess of (CASTERLEVEL+4) gain a +4 circumstance bonus on their saves to avoid being intimidated in this way. This intimidation effect is a mind-affecting fear effect.") },
    SpellListEntry { key: "Tidal Surge", name_pi_line: None, school: Some(Pf1SchoolId::Conjuration), level: Some(5), description: Some("If you cast tidal surge on land, you create an onrushing surge of water 10 feet high in a 30-foot cone that deals (min(10,CASTERLEVEL/2))d6 points of bludgeoning damage and extinguishes all nonmagical fires in the area. Magical fire effects in the area of a tidal surge are affected as if you had cast dispel magic. In addition to taking damage, creatures that fail their Reflex saves are pushed 1d4x5 feet away from you, and Medium or smaller creatures are also knocked prone. If you cast this spell in or on a body of water at least 30 feet across, you can shape the spell either as the cone described above or as a 60-foot line. In either shape, the water deals 1d10 points of bludgeoning damage for every 2 caster levels you have in addition to pushing away creatures that fail their Reflex saves.") },
    SpellListEntry { key: "Vigilant Rest", name_pi_line: None, school: Some(Pf1SchoolId::Abjuration), level: Some(3), description: Some("While the target of this spell is asleep, she retains some of her normal powers of perception. While she tunes out harmless sounds such as the crackling of the campfire, crickets, or light breezes, she does not take the normal +10 modifier to the DC of Perception checks she attempts while asleep. If the target detects a threat or unexplained noise while sleeping, she can wake immediately and stand up from her sleeping position as a free action. If the target is roused but returns to sleep during the spell's duration, she falls asleep immediately and does not count as having her sleep interrupted, even if she engaged in combat while she was awake.") },
    SpellListEntry { key: "Vine Strike", name_pi_line: None, school: Some(Pf1SchoolId::Conjuration), level: Some(2), description: Some("Bristles burst from your body, lodging in your opponent and blossoming into entangling vines as you pummel your target. While this spell is in effect, one of your natural attacks or unarmed strikes deals an additional 1d6 points of damage, and each creature hit with that natural weapon or unarmed strike must succeed at a Reflex save or be entangled for the duration of the spell; on a successful Reflex save, the creature is immune to the entangled effect for 1 round. A creature entangled by this spell can spend a standard action to remove the vines, but can be entangled again by further unarmed strikes.") },
    SpellListEntry { key: "Wandering Weather", name_pi_line: None, school: Some(Pf1SchoolId::Transmutation), level: Some(8), description: Some("This spell functions as control weather except you can opt for the weather to remain centered on you as you move.") },
    SpellListEntry { key: "Winter Grasp", name_pi_line: None, school: Some(Pf1SchoolId::Conjuration), level: Some(2), description: Some("Ice encrusts the ground, radiating supernatural cold and making it hard for creatures to maintain their balance. This icy ground is treated as normal ice, forcing creatures to spend 2 squares of movement to enter an icy square and increasing the DC of Acrobatics checks in the area by 5. A creature that begins its turn in the affected area takes 1d6 points of cold damage and takes a -2 penalty on saving throws against spells with the cold descriptor for 1 round.") },
    SpellListEntry { key: "With the Wind", name_pi_line: None, school: Some(Pf1SchoolId::Abjuration), level: Some(2), description: Some("You create eddies in the air around the subject that protect it from being checked or blown away. The target can't be moved by winds of less than windstorm force unless it wishes to be.") },
    SpellListEntry { key: "Green Caress", name_pi_line: None, school: Some(Pf1SchoolId::Transmutation), level: Some(4), description: Some("You cause the target to transform into a plant over time. You must succeed at a melee touch attack to infect the target. If the target succeeds at its Fortitude saving throw, it takes 1d4 points of ability damage to each physical ability score (Strength, Dexterity, and Constitution) and the spell ends. If the target fails its saving throw, it takes 1d4 points of ability damage to each physical ability score immediately and continues to take 1d4 points of ability damage to each of its physical ability scores every day, until the spell expires. It can't recover this ability damage as long as the spell lasts, even with magic. While the spell continues, the target takes on physical plant characteristics as appropriate to the environment. It begins to diminish in height and its skin turns plantlike. For example, the target's skin might turn green and its hair is slowly replaced with grass or leaves or the target's skin might become smooth, pale, and flabby as the creature transforms into a large mushroom in an underground environment. &nl;If the damage to any single ability score equals or exceeds that score, the target fully transforms into a normal small tree or shrub. This final transformation is instantaneous, ending green caress. The target remains alive but is considered the same as a regular tree, shrub, or other vegetation. Any ability damage from other sources, like poison or disease, also applies toward transforming the creature. If the target retains at least 1 point in all of its physical ability scores at the end of 7 days, the final transformation doesn't occur and the spell ends. Any changes in appearance gradually reverse themselves as the ability damage heals. &nl;Break enchantment, dispel magic, and remove curse can end the spell before the duration expires, but the spell is contagious. If a caster level check attempt to remove green caress fails by 5 or more, the creature who attempted to remove the effect must attempt a Fortitude saving throw as if it had just been targeted with the spell. If the spell's target attempts to remove the effect from itself and fails, it causes the spell to behave as if affected by plant growth (as described below). &nl;Polymorph any object ends the spell and totally restores the target without any risk to the caster, even after the target has been finally transformed, as do limited wish, miracle, and wish (treat polymorph any object as if it had an instantaneous duration if it is used in this way). If the target is in the area of a plant growth spell as it is cast, it must attempt a Fortitude save at green caress's DC or immediately take another 1d4 points of ability damage to each physical ability score; this stacks with multiple castings of plant growth. If the target is in the area of diminish plants as it is cast, it ignores the next ability damage from green caress to one of its three physical ability scores (chosen randomly); this doesn't stack with multiple castings of diminish plants.") },
    SpellListEntry { key: "Verminous Transformation", name_pi_line: None, school: Some(Pf1SchoolId::Transmutation), level: Some(6), description: Some("You partially transform your body into a swarm of bats, insects, rats, and spiders. As a standard action, you can send out a piece of your body to attack up to four Medium or smaller creatures (or one larger creature) within 10 feet of you. The creatures take 4d6 points of damage and must succeed at a Fortitude save or take 1d3 points of Constitution damage and 1d3 points of Strength damage; the ability damage is a poison effect. Abilities that protect against swarm attacks apply to this damage and spell resistance applies. Additionally, since your body is partially a swarm, you take only half damage from piercing and slashing attacks, unless those attacks would deal full damage or greater to a swarm (for instance, an area piercing attack would deal full damage to you). You can still be targeted by single-target spells but you gain a +2 circumstance bonus on any saving throws against them. Casting spells in this form is difficult and any spells with somatic components require a concentration check as if casting defensively; if you are also casting the spell defensively, roll a single concentration check at a -5 penalty.") },
    SpellListEntry { key: "Seed Spies", name_pi_line: None, school: Some(Pf1SchoolId::Divination), level: Some(2), description: Some("You summon one or more wafting seeds, which have a measure of intelligence and make for excellent spies. When they are in your presence, the seeds obey your mental commands, and you can issue orders to any number of them as a single standard action, provided that you issue the same orders to each one. In order to issue different orders to different seeds, you must spend a separate standard action for each set of orders. A seed in physical contact with you can answer simple questions about what it has observed, at a rate of one question per round. The seeds can hear but not see. It can relate only what it perceived with its senses, and can't repeat speech. It has difficulty making subjective judgments, and questions that demand such reasoning are unlikely to yield a clear answer. For example, a seed is unable to relay someone's emotional state or determine who among several people it heard might be in charge. Each seeds' size is Fine. Each seed has 1 hit point, AC 20, and a fly speed of 10 feet (good maneuverability). They can't crawl or climb, although they can cling to rough, soft, or sticky creatures or surfaces. The seeds use your saving throw bonuses, have a Perception skill bonus of %1, and can't make attacks. They can make Stealth checks to avoid being noticed even if they lack a source of cover or concealment, and they have a Stealth skill bonus of %2. The seeds can even cling onto creatures of Tiny or larger size while using Stealth, possibly riding on those creatures unnoticed. A Tiny creature gains a +16 bonus on Perception checks made to notice one of these seeds currently clinging to it. For each size category larger than Tiny the creature being clung to, this bonus is reduced by 4 (to a minimum of +0 for Huge or larger creatures). You also maintain a faint mystical connection with these seeds, which allows you to sense where they are. As a full-round action, you can concentrate on the spell in order to learn the direction and relative distance of each of the seeds.") },
    SpellListEntry { key: "Waft", name_pi_line: None, school: Some(Pf1SchoolId::Transmutation), level: Some(5), description: Some("You make the targets light enough to be carried by wind. Creatures affected by this spell suffer cumulative penalties for attacking as if under the effects of levitate unless they have a fly speed. Treat each target as two size categories lighter for the purposes of being checked or blown away by wind. If a target has a fly speed, it can fly overland at the wind's speed in the same direction as the wind by succeeding at a DC 20 Fly check. If a creature flying overland this way attempts to change direction, it risks being blown away as usual. By linking hands or creating a connection with rope, creatures affected by this spell can be towed through the air by a flying creature as if each weighed only one-eighth its actual weight.") },
    SpellListEntry { key: "Wing Bounty", name_pi_line: None, school: Some(Pf1SchoolId::Conjuration), level: Some(2), description: Some("Your wings sprout a variety of colorful and flavorful berries. Each berry functions as if affected by goodberry. You can choose for one affected berry to also be poisonous (as striped toadstool); only you and druids of 5th level or higher can tell which is which without magic.") },
    SpellListEntry { key: "Wing Thorns", name_pi_line: None, school: Some(Pf1SchoolId::Transmutation), level: Some(3), description: Some("Your wings sprout poisonous thorns each the size of a dagger. You can use these thorns like armor spikes. In addition, you can make two wing attacks as primary natural weapons. If you are Small, the wings deal 1d3 points of bludgeoning and piercing damage plus your Strength modifier (unless you also attack with a weapon, in which case they are treated as a secondary natural weapon). A creature damaged by your wing thorns experiences intense itching, gaining the sickened condition while the spell lasts unless it succeeds at a Fortitude saving throw.") },
    SpellListEntry { key: "Wooden Wing Shield", name_pi_line: None, school: Some(Pf1SchoolId::Transmutation), level: Some(4), description: Some("Your wings transmute into a wooden barrier resembling a tower shield to block attacks, granting you a +4 shield bonus to AC. If you move, the spell ends immediately.") },
    SpellListEntry { key: "Delectable Flesh", name_pi_line: None, school: Some(Pf1SchoolId::Transmutation), level: Some(6), description: Some("Choose a creature within range as the object of hunger. All other creatures within 15 feet of the target that can see or smell the target's delectable flesh must succeed at a Will save or spiral into a depraved state from which they gain a single purpose-to consume as much of the target's delicious flesh as possible. The creature chosen as the target of this spell is not affected by this depravity. A depraved creature gains a bite attack, two claw attacks, and the scent ability if it didn't already have them. It drops any items it was carrying and attacks the target of the spell with these natural weapons, acting as if it were confused and the target had attacked it first. This effect lasts for the spell's duration or until the depraved creature can no longer see or smell the object of its hunger for a full minute. Additionally, a depraved creature can attempt a new saving throw to end this effect at the end of any turn in which the affected creature makes an attack against the object of its hunger. If a creature that eats for nourishment succeeds at a save to end the depraved effect early, it takes a -2 penalty on ability checks, attack rolls, concentration checks, saving throws, and skill checks whenever it is within 15 feet of the target.") },
    SpellListEntry { key: "Grasping Vine", name_pi_line: None, school: Some(Pf1SchoolId::Transmutation), level: Some(2), description: Some("You cause a long, thin vine to sprout from your body-typically from the center of your chest or from the palm of an outstretched hand. As a standard action, you can direct the end of the vine to move to any square within 20 feet of you and perform one of the following tasks: deliver a touch spell that you cast after the vine has grown, pick up an unattended object weighing 20 pounds or less, give a held object to another creature, attempt to disable a trap or lock using your Disable Device modifier with a -2 penalty, or perform any other task that the GM deems reasonable. The vine does not threaten squares and cannot make attacks of opportunity, nor can it wield weapons.") },
    SpellListEntry { key: "Leshy Swarm", name_pi_line: None, school: Some(Pf1SchoolId::Conjuration), level: Some(3), description: Some("You call out to nearby nature spirits and grant them temporary plant bodies. These creatures are similar to leshys, except they are Tiny and far more simpleminded. The swarm uses the statistics for a rat swarm, except it does not carry a disease or have scent. The leshy swarm has darkvision with a range of 60 feet and is immune to electricity, mind-affecting effects, paralysis, poison, polymorph, sleep effects, sonic, and stunning. You can direct the leshy swarm to move up to its speed along a path for your choice by spending a standard action to communicate your desires through the spell, or by spending a move action if you can speak to creatures that understand only Druidic and Sylvan. The leshys are confused by their sudden possession of new bodies and assume that nearly any creature you direct them toward is a threat. They attack all creatures within their area except for you and other creatures with the plant type.") },
    SpellListEntry { key: "Animal Growth (Reptiles Only)", name_pi_line: None, school: Some(Pf1SchoolId::Transmutation), level: Some(5), description: Some("The target reptile grows to twice its normal size and eight times its normal weight.") },
    SpellListEntry { key: "Animal Shapes (Reptiles Only)", name_pi_line: None, school: Some(Pf1SchoolId::Transmutation), level: Some(8), description: Some("You change the form of up to (CASTERLEVEL) willing reptiles into an animal of your choice.") },
];
